<?php require __DIR__.'/../bootstrap/app.php';$title='Projects';require __DIR__.'/../app/Views/header.php';?><section class="pagehead"><div class="container"><h1>Projects</h1><p>Completed and ongoing project portfolio.</p></div></section><section class="section"><div class="container"><div class="cardx">Project entries and galleries are represented in the database foundation; publishing screens remain to be built.</div></div></section><?php $pr=Database::get()->query("SELECT title,sector,description,status FROM projects ORDER BY id DESC")->fetchAll();if($pr):?><section class="section"><div class="container"><h2>Latest projects</h2><div class="row"><?php foreach($pr as $x):?><div class="col-md-4 mb-3"><div class="cardx h-100"><h3><?=e($x['title'])?></h3><small><?=e($x['sector'])?> · <?=e($x['status'])?></small><p><?=e($x['description'])?></p></div></div><?php endforeach;?></div></div></section><?php endif;?><?php require __DIR__.'/../app/Views/footer.php';?>